        var bindCalls = new AtomicInteger();
        var continuationCalls = new AtomicInteger();
        F7<Integer, Integer, Integer, Integer, Integer, Integer, Integer, Integer> source = (a, b, c, d, e, f, g) -> { sourceCalls.incrementAndGet(); return 1 * a + 2 * b + 3 * c + 4 * d + 5 * e + 6 * f + 7 * g; };
